class Zipper:
    def __init__(self, focus, trail):
        self._focus = focus
        self._trail = trail

    @staticmethod
    def from_tree(tree):
        return Zipper(tree, [])

    def value(self):
        return self._focus["value"]

    def set_value(self, value):
        return Zipper(
            {"value": value, "left": self._focus["left"], "right": self._focus["right"]},
            self._trail,
        )

    def left(self):
        if self._focus["left"] is None:
            return None
        return Zipper(self._focus["left"], self._trail + [(self._focus, "left")])

    def set_left(self, subtree):
        focus = dict(self._focus)
        focus["left"] = subtree
        return Zipper(focus, self._trail)

    def right(self):
        if self._focus["right"] is None:
            return None
        return Zipper(self._focus["right"], self._trail + [(self._focus, "right")])

    def set_right(self, subtree):
        focus = dict(self._focus)
        focus["right"] = subtree
        return Zipper(focus, self._trail)

    def up(self):
        if not self._trail:
            return None
        parent, direction = self._trail[-1]
        new_parent = dict(parent)
        new_parent[direction] = self._focus
        return Zipper(new_parent, self._trail[:-1])

    def to_tree(self):
        zipper = self
        while zipper._trail:
            zipper = zipper.up()
        return zipper._focus

